import 'dart:convert';
import 'dart:math' as math;
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

class WorkProject {
  const WorkProject({required this.id,required this.name,this.client='',this.address='',this.floors='',this.structure='',this.notes='',required this.createdAt});
  final String id,name,client,address,floors,structure,notes,createdAt;
  Map<String,dynamic> toJson()=>{'id':id,'name':name,'client':client,'address':address,'floors':floors,'structure':structure,'notes':notes,'createdAt':createdAt};
  factory WorkProject.fromJson(Map<String,dynamic> j)=>WorkProject(id:j['id']?.toString()??'',name:j['name']?.toString()??'',client:j['client']?.toString()??'',address:j['address']?.toString()??'',floors:j['floors']?.toString()??'',structure:j['structure']?.toString()??'',notes:j['notes']?.toString()??'',createdAt:j['createdAt']?.toString()??'');
}

class WorkspaceStore {
  static const _pk='workspace.projects.v1',_hk='workspace.history.v1',_activeKey='workspace.activeProject.v1';
  static Future<List<WorkProject>> projects() async {final p=await SharedPreferences.getInstance();try{return (jsonDecode(p.getString(_pk)??'[]') as List).map((e)=>WorkProject.fromJson(Map<String,dynamic>.from(e as Map))).toList();}catch(_){return [];}}
  static Future<void> saveProject(WorkProject v) async {final a=await projects();final i=a.indexWhere((x)=>x.id==v.id);if(i<0){a.insert(0,v);}else{a[i]=v;}final p=await SharedPreferences.getInstance();await p.setString(_pk,jsonEncode(a.map((x)=>x.toJson()).toList()));}
  static Future<void> deleteProject(String id) async {final a=await projects()..removeWhere((x)=>x.id==id);final p=await SharedPreferences.getInstance();await p.setString(_pk,jsonEncode(a.map((x)=>x.toJson()).toList()));}
  static Future<WorkProject?> activeProject() async {final p=await SharedPreferences.getInstance();final id=p.getString(_activeKey);if(id==null)return null;final all=await projects();for(final project in all){if(project.id==id)return project;}return null;}\n  static Future<void> setActiveProject(String? id) async {final p=await SharedPreferences.getInstance();if(id==null){await p.remove(_activeKey);}else{await p.setString(_activeKey,id);}}\n  static Future<void> addHistory({required String title,required String formula,required String result,required String inputs,String? projectId,String? projectName}) async {final p=await SharedPreferences.getInstance();List<dynamic> a=[];try{a=List<dynamic>.from(jsonDecode(p.getString(_hk)??'[]') as List);}catch(_){}a.insert(0,{'title':title,'formula':formula,'result':result,'inputs':inputs,'projectId':projectId,'projectName':projectName,'at':DateTime.now().toIso8601String()});if(a.length>300)a=a.take(300).toList();await p.setString(_hk,jsonEncode(a));}
  static Future<List<Map<String,dynamic>>> history() async {final p=await SharedPreferences.getInstance();try{return (jsonDecode(p.getString(_hk)??'[]') as List).map((e)=>Map<String,dynamic>.from(e as Map)).toList();}catch(_){return [];}}
  static Future<void> clearHistory() async {final p=await SharedPreferences.getInstance();await p.remove(_hk);}
}

class WorkspacePage extends StatefulWidget {const WorkspacePage({super.key});@override State<WorkspacePage> createState()=>_WorkspacePageState();}
class _WorkspacePageState extends State<WorkspacePage>{
 int tab=0;
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('فضای کار مهندسی')),body:IndexedStack(index:tab,children:const [_ProjectsTab(),_HistoryTab(),_ConverterTab(),_FormulaTab(),_CostTab()]),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const [NavigationDestination(icon:Icon(Icons.apartment),label:'پروژه‌ها'),NavigationDestination(icon:Icon(Icons.history),label:'سوابق'),NavigationDestination(icon:Icon(Icons.swap_horiz),label:'تبدیل واحد'),NavigationDestination(icon:Icon(Icons.functions),label:'فرمول‌ها'),NavigationDestination(icon:Icon(Icons.payments),label:'هزینه')]));
}

class _ProjectsTab extends StatefulWidget {const _ProjectsTab();@override State<_ProjectsTab> createState()=>_ProjectsTabState();}
class _ProjectsTabState extends State<_ProjectsTab>{
 late Future<List<WorkProject>> data;
 @override void initState(){super.initState();reload();}
 void reload()=>data=WorkspaceStore.projects();
 Future<void> edit([WorkProject? p]) async {final v=await Navigator.push<WorkProject>(context,MaterialPageRoute(builder:(_)=>_ProjectEditor(project:p)));if(v!=null){await WorkspaceStore.saveProject(v);setState(reload);}}
 @override Widget build(BuildContext context)=>FutureBuilder<List<WorkProject>>(future:data,builder:(c,s){final a=s.data??[];return ListView(padding:const EdgeInsets.all(16),children:[Row(children:[const Expanded(child:Text('پرونده پروژه‌ها',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),FilledButton.icon(onPressed:()=>edit(),icon:const Icon(Icons.add),label:const Text('پروژه جدید'))]),const SizedBox(height:10),if(s.connectionState!=ConnectionState.done)const Center(child:CircularProgressIndicator())else if(a.isEmpty)const Text('هنوز پروژه‌ای ثبت نشده است.') else for(final p in a)Card(child:ListTile(title:Text(p.name),subtitle:Text([p.client,p.address,p.floors.isEmpty?'':'طبقات: '+p.floors].where((x)=>x.isNotEmpty).join(' • ')),onTap:()=>edit(p),trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='edit'){await edit(p);}else if(v=='active'){await WorkspaceStore.setActiveProject(p.id);if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('پروژه «'+p.name+'» برای محاسبات بعدی انتخاب شد.')));setState(reload);}else{await WorkspaceStore.deleteProject(p.id);final active=await WorkspaceStore.activeProject();if(active==null)await WorkspaceStore.setActiveProject(null);setState(reload);}},itemBuilder:(_)=>const [PopupMenuItem(value:'active',child:Text('انتخاب برای محاسبات')),PopupMenuItem(value:'edit',child:Text('ویرایش')),PopupMenuItem(value:'delete',child:Text('حذف'))])))]);});
}
class _ProjectEditor extends StatefulWidget {const _ProjectEditor({this.project});final WorkProject? project;@override State<_ProjectEditor> createState()=>_ProjectEditorState();}
class _ProjectEditorState extends State<_ProjectEditor>{
 late final name=TextEditingController(text:widget.project?.name??''),client=TextEditingController(text:widget.project?.client??''),address=TextEditingController(text:widget.project?.address??''),floors=TextEditingController(text:widget.project?.floors??''),structure=TextEditingController(text:widget.project?.structure??''),notes=TextEditingController(text:widget.project?.notes??'');
 @override void dispose(){for(final c in [name,client,address,floors,structure,notes]){c.dispose();}super.dispose();}
 Widget field(TextEditingController c,String l)=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:c,decoration:InputDecoration(labelText:l)));
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.project==null?'ثبت پروژه':'ویرایش پروژه')),body:ListView(padding:const EdgeInsets.all(16),children:[field(name,'نام پروژه *'),field(client,'نام کارفرما'),field(address,'نشانی پروژه'),field(floors,'تعداد طبقات'),field(structure,'مشخصات سازه'),field(notes,'توضیحات'),FilledButton(onPressed:(){if(name.text.trim().isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('نام پروژه الزامی است.')));return;}final p=widget.project;Navigator.pop(context,WorkProject(id:p?.id??DateTime.now().microsecondsSinceEpoch.toString(),name:name.text.trim(),client:client.text.trim(),address:address.text.trim(),floors:floors.text.trim(),structure:structure.text.trim(),notes:notes.text.trim(),createdAt:p?.createdAt??DateTime.now().toIso8601String()));},child:const Text('ذخیره پروژه'))]));
}

class _HistoryTab extends StatefulWidget {const _HistoryTab();@override State<_HistoryTab> createState()=>_HistoryTabState();}
class _HistoryTabState extends State<_HistoryTab>{late Future<List<Map<String,dynamic>>> data;@override void initState(){super.initState();reload();}void reload()=>data=WorkspaceStore.history();
 @override Widget build(BuildContext context)=>FutureBuilder<List<Map<String,dynamic>>>(future:data,builder:(c,s){final a=s.data??[];return ListView(padding:const EdgeInsets.all(16),children:[Row(children:[const Expanded(child:Text('سوابق محاسبات',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),TextButton(onPressed:a.isEmpty?null:()async{await WorkspaceStore.clearHistory();setState(reload);},child:const Text('پاک‌کردن'))]),if(s.connectionState!=ConnectionState.done)const Center(child:CircularProgressIndicator())else if(a.isEmpty)const Text('نتایج محاسبات انجام‌شده در این بخش ذخیره می‌شوند.')else for(final x in a)Card(child:ExpansionTile(title:Text(x['title']?.toString()??''),subtitle:Text([x['result']?.toString()??'',if((x['projectName']?.toString()??'').isNotEmpty)'پروژه: '+x['projectName'].toString()].join(' • ')),childrenPadding:const EdgeInsets.all(14),children:[Text('فرمول: '+(x['formula']?.toString()??'')),Text('ورودی‌ها: '+(x['inputs']?.toString()??'')),Text('زمان: '+(x['at']?.toString()??''))]))]);});}

class _ConverterTab extends StatefulWidget {const _ConverterTab();@override State<_ConverterTab> createState()=>_ConverterTabState();}
class _ConverterTabState extends State<_ConverterTab>{
 final input=TextEditingController(text:'1');String kind='طول',result='';static const labels={'طول':'متر به سانتی‌متر','مساحت':'مترمربع به سانتی‌مترمربع','حجم':'مترمکعب به لیتر','وزن':'کیلوگرم به تن','قطر':'میلی‌متر به متر','اینچ':'اینچ به میلی‌متر','شیب':'درجه به درصد شیب'};
 void calc(){var raw=input.text;const fa='۰۱۲۳۴۵۶۷۸۹',ar='٠١٢٣٤٥٦٧٨٩';for(var i=0;i<10;i++){raw=raw.replaceAll(fa[i],String.fromCharCode(48+i)).replaceAll(ar[i],String.fromCharCode(48+i));}final v=double.tryParse(raw.replaceAll('٫','.').replaceAll(',','.').replaceAll('٬',''));if(v==null||!v.isFinite||v<0){setState(()=>result='عدد معتبر و غیرمنفی وارد کنید.');return;}if(kind=='شیب'){if(v>=90){setState(()=>result='زاویه باید کمتر از ۹۰ درجه باشد.');return;}final percent=math.tan(v*math.pi/180)*100;setState(()=>result='درصد شیب: '+percent.toStringAsFixed(3)+'٪');return;}final factors={'طول':100.0,'مساحت':10000.0,'حجم':1000.0,'وزن':.001,'قطر':.001,'اینچ':25.4};setState(()=>result=labels[kind].toString()+': '+(v*factors[kind]!).toStringAsFixed(4));}
 @override void dispose(){input.dispose();super.dispose();}
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('تبدیل واحدهای مهندسی',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),DropdownButtonFormField<String>(value:kind,items:labels.entries.map((e)=>DropdownMenuItem(value:e.key,child:Text(e.value))).toList(),onChanged:(v){if(v!=null)setState(()=>kind=v);}),const SizedBox(height:12),TextField(controller:input,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'مقدار')),FilledButton(onPressed:calc,child:const Text('تبدیل')),Card(child:Padding(padding:const EdgeInsets.all(16),child:Text(result)))]);
}

class _FormulaTab extends StatelessWidget {const _FormulaTab();static const rows=[('حجم عضو مستطیلی','طول × عرض × ارتفاع','مترمکعب'),('وزن میلگرد','قطر² ÷ ۱۶۲ × طول','قطر: میلی‌متر، طول: متر، خروجی: کیلوگرم'),('مساحت مستطیل','طول × عرض','مترمربع'),('حجم بتن با پرت','حجم خالص × (۱ + درصد پرت ÷ ۱۰۰)','برآورد سفارش'),('حمل خاک','حجم متورم ÷ ظرفیت کامیون','تعداد سرویس رو به بالا'),('درصد شیب','اختلاف ارتفاع ÷ طول افقی × ۱۰۰','درصد'),('هزینه مصالح','مقدار × قیمت واحد','تومان')];@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('بانک فرمول‌های پایه',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),for(final r in rows)Card(child:ListTile(title:Text(r.$1),subtitle:Text(r.$2+'\n'+r.$3)))]);}

class _CostTab extends StatefulWidget {const _CostTab();@override State<_CostTab> createState()=>_CostTabState();}
class _CostTabState extends State<_CostTab>{final qty=TextEditingController(text:'1'),price=TextEditingController(text:'0'),labor=TextEditingController(text:'0'),transport=TextEditingController(text:'0'),waste=TextEditingController(text:'0');String result='';double n(TextEditingController c)=>double.tryParse(c.text.replaceAll(',','').replaceAll('٫','.'))??double.nan;@override void dispose(){for(final c in [qty,price,labor,transport,waste]){c.dispose();}super.dispose();}Widget f(TextEditingController c,String l)=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:c,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:l)));void calc(){final q=n(qty),p=n(price),l=n(labor),t=n(transport),w=n(waste);if([q,p,l,t,w].any((v)=>!v.isFinite||v<0)||q<=0){setState(()=>result='مقادیر واردشده معتبر نیستند.');return;}final m=q*p*(1+w/100),lab=q*l;setState(()=>result='هزینه مصالح با پرت: '+m.toStringAsFixed(0)+' تومان\nدستمزد: '+lab.toStringAsFixed(0)+' تومان\nحمل: '+t.toStringAsFixed(0)+' تومان\nجمع کل: '+(m+lab+t).toStringAsFixed(0)+' تومان');}@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('برآورد هزینه عملیات',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const Text('قیمت‌ها را خودتان وارد کنید؛ این بخش قیمت لحظه‌ای بازار نیست.'),const SizedBox(height:12),f(qty,'مقدار'),f(price,'قیمت واحد مصالح (تومان)'),f(labor,'دستمزد واحد (تومان)'),f(transport,'هزینه حمل (تومان)'),f(waste,'درصد پرت'),FilledButton(onPressed:calc,child:const Text('محاسبه هزینه')),Card(child:Padding(padding:const EdgeInsets.all(16),child:Text(result,style:const TextStyle(height:1.8))))]);}
